-- The cases of test_run_plan_asof: each COPY line below is one case, an ASOF
-- LEFT JOIN DuckDB runs over the files of data.sql, and the file its answer
-- goes to, `<case>_<parquet|csv>.tsv`. The columns are the as-of node's own:
-- the left side's, then the right side's, a right column whose name the left
-- side uses suffixed `_right`. The test builds each node from its own table
-- of the cases (the sides' columns, keys and direction) and holds its rows to
-- these answers, so the SQL is DuckDB's alone.
COPY (SELECT t.id AS id, t.sym AS sym, t.ts AS ts, q.sym AS sym_right, q.ts AS ts_right, q.px AS px, q.qid AS qid FROM read_parquet('t.parquet') t ASOF LEFT JOIN read_parquet('q.parquet') q ON t.sym = q.sym AND t.ts >= q.ts) TO 'backward_keyed_parquet.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.sym AS sym, t.ts AS ts, q.sym AS sym_right, q.ts AS ts_right, q.px AS px, q.qid AS qid FROM read_csv('t.csv') t ASOF LEFT JOIN read_csv('q.csv') q ON t.sym = q.sym AND t.ts >= q.ts) TO 'backward_keyed_csv.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.sym AS sym, t.ts AS ts, q.sym AS sym_right, q.ts AS ts_right, q.px AS px, q.qid AS qid FROM read_parquet('t.parquet') t ASOF LEFT JOIN read_parquet('q.parquet') q ON t.sym = q.sym AND t.ts <= q.ts) TO 'forward_keyed_parquet.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.sym AS sym, t.ts AS ts, q.sym AS sym_right, q.ts AS ts_right, q.px AS px, q.qid AS qid FROM read_csv('t.csv') t ASOF LEFT JOIN read_csv('q.csv') q ON t.sym = q.sym AND t.ts <= q.ts) TO 'forward_keyed_csv.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.sym AS sym, t.ts AS ts, q.sym AS sym_right, q.ts AS ts_right, q.px AS px, q.qid AS qid FROM read_parquet('t.parquet') t ASOF LEFT JOIN read_parquet('q.parquet') q ON t.ts >= q.ts) TO 'backward_no_key_parquet.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.sym AS sym, t.ts AS ts, q.sym AS sym_right, q.ts AS ts_right, q.px AS px, q.qid AS qid FROM read_csv('t.csv') t ASOF LEFT JOIN read_csv('q.csv') q ON t.ts >= q.ts) TO 'backward_no_key_csv.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.sym AS sym, t.ts AS ts, q.sym AS sym_right, q.ts AS ts_right, q.px AS px, q.qid AS qid FROM read_parquet('t.parquet') t ASOF LEFT JOIN read_parquet('q.parquet') q ON t.ts <= q.ts) TO 'forward_no_key_parquet.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.sym AS sym, t.ts AS ts, q.sym AS sym_right, q.ts AS ts_right, q.px AS px, q.qid AS qid FROM read_csv('t.csv') t ASOF LEFT JOIN read_csv('q.csv') q ON t.ts <= q.ts) TO 'forward_no_key_csv.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.sym AS sym, t.tts AS tts, q.sym AS sym_right, q.tts AS tts_right, q.px AS px, q.qid AS qid FROM read_parquet('t.parquet') t ASOF LEFT JOIN read_parquet('q.parquet') q ON t.sym = q.sym AND t.tts >= q.tts) TO 'backward_timestamp_parquet.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.sym AS sym, t.tts AS tts, q.sym AS sym_right, q.tts AS tts_right, q.px AS px, q.qid AS qid FROM read_parquet('t.parquet') t ASOF LEFT JOIN read_parquet('q.parquet') q ON t.sym = q.sym AND t.tts <= q.tts) TO 'forward_timestamp_parquet.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.sym AS sym, t.ts AS ts, q.sym AS sym_right, q.qid AS qid, q.ts AS ts_right, q.px AS px FROM read_parquet('t.parquet') t ASOF LEFT JOIN read_parquet('q.parquet') q ON t.sym = q.sym AND t.id = q.qid AND t.ts >= q.ts) TO 'backward_two_keys_parquet.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.sym AS sym, t.ts AS ts, q.sym AS sym_right, q.qid AS qid, q.ts AS ts_right, q.px AS px FROM read_csv('t.csv') t ASOF LEFT JOIN read_csv('q.csv') q ON t.sym = q.sym AND t.id = q.qid AND t.ts >= q.ts) TO 'backward_two_keys_csv.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.sym AS sym, t.ts AS ts, q.sym AS sym_right, q.ts AS ts_right, q.px AS px, q.qid AS qid FROM read_parquet('t.parquet') t ASOF LEFT JOIN read_parquet('q2.parquet') q ON t.sym = q.sym AND t.ts >= q.ts) TO 'backward_ties_reordered_parquet.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
