COPY (SELECT t.id AS id, t.sym AS sym, t.ts AS ts, q.sym AS sym_right, q.ts AS ts_right, q.px AS px, q.qid AS qid FROM read_parquet('t.parquet') t ASOF LEFT JOIN read_parquet('e.parquet') q ON t.sym = q.sym AND t.ts >= q.ts) TO 'backward_empty_right_parquet.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT t.id AS id, t.sym AS sym, t.ts AS ts, q.sym AS sym_right, q.ts AS ts_right, q.px AS px, q.qid AS qid FROM read_parquet('te.parquet') t ASOF LEFT JOIN read_parquet('q.parquet') q ON t.sym = q.sym AND t.ts >= q.ts) TO 'backward_empty_left_parquet.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
